function construct_direct_gsn_basis_ys_s0(lambda, m, nu, omega)
    lambda = ComplexF64(lambda)
    m = Float64(m)
    nu = Float64(nu)
    omega = ComplexF64(omega)
    m2 = m * m
    o2 = omega * omega
    s1 = sin(nu)
    c1 = sqrt((1 - s1) * (1 + s1))
    sn = s1
    sn2 = sn * sn
    sn3 = sn2 * sn
    sn4 = sn3 * sn
    sn5 = sn4 * sn
    sn6 = sn5 * sn
    sn7 = sn6 * sn
